BEGIN;
DO $$
DECLARE admin_session text; s1 text; s2 text; learner_session text; child_session text; a text; b text; learner text; child text; grandchild text; new_child text; code_a text; code_l text; code_c text; code_g text; res jsonb; st jsonb; uid text; regid text; k integer; i integer; result jsonb;
BEGIN
 res:=hn.api(jsonb_build_object('action','login','username','adminsss','password',current_setting('hn.test_admin_password',true)));admin_session:=res->>'sessionToken';ASSERT admin_session IS NOT NULL,'Admin login failed: '||res::text;
 res:=hn.api(jsonb_build_object('action','register','name','TEST Trợ lực A','phone','0990000001','consent',true));ASSERT res->>'error' IS NULL,res::text;s1:=res->>'sessionToken';code_a:=res->'account'->>'code';SELECT id INTO a FROM hn.users WHERE username='0990000001';
 ASSERT (SELECT role FROM hn.users WHERE id=a)='student','Self-assigned elevated role';
 res:=hn.api(jsonb_build_object('action','register','name','TEST Trợ lực B','phone','0990000002','consent',true));s2:=res->>'sessionToken';SELECT id INTO b FROM hn.users WHERE username='0990000002';
 res:=hn.api(jsonb_build_object('action','role','sessionToken',s1,'userId',a,'role','staff'));ASSERT res ? 'error','Learner granted own staff role';
 res:=hn.api(jsonb_build_object('action','role','sessionToken',admin_session,'userId',a,'role','staff'));ASSERT NOT(res ? 'error'),res::text;
 res:=hn.api(jsonb_build_object('action','role','sessionToken',admin_session,'userId',b,'role','staff'));ASSERT NOT(res ? 'error'),res::text;
 res:=hn.api(jsonb_build_object('action','registerZoom','name','TEST Học viên gốc','phone','0990000003','consent',true,'ref',code_a,'topic','1h viết lại tương lai'));learner_session:=res->>'sessionToken';code_l:=res->'account'->>'code';SELECT id INTO learner FROM hn.users WHERE username='0990000003';ASSERT (SELECT assigned FROM hn.users WHERE id=learner)=a,'Root failed inherited ownership';
 res:=hn.api(jsonb_build_object('action','registerZoom','name','TEST Tầng 2','phone','0990000004','consent',true,'ref',code_l));child_session:=res->>'sessionToken';code_c:=res->'account'->>'code';SELECT id INTO child FROM hn.users WHERE username='0990000004';
 res:=hn.api(jsonb_build_object('action','registerZoom','name','TEST Tầng 3','phone','0990000005','consent',true,'ref',code_c));code_g:=res->'account'->>'code';SELECT id INTO grandchild FROM hn.users WHERE username='0990000005';
 st:=hn.api(jsonb_build_object('action','state','sessionToken',s1));ASSERT jsonb_array_length(st->'people')=3,st::text;
 st:=hn.api(jsonb_build_object('action','state','sessionToken',s2));ASSERT jsonb_array_length(st->'people')=0,'Out of branch data leaked';
 st:=hn.api(jsonb_build_object('action','state','sessionToken',learner_session));ASSERT jsonb_array_length(st->'refs')=1,'Learner sees extra levels';ASSERT st->'refs'->0=jsonb_build_object('name','TEST Tầng 2'),'Learner data should contain only name';ASSERT jsonb_array_length(st->'people')=0,'Learner accessed CRM';ASSERT NOT((st->'me') ? 'password_hash'),'Password hash leaked';
 res:=hn.api(jsonb_build_object('action','assign','sessionToken',s1,'userId',learner,'assigned',b));ASSERT res ? 'error','Staff transferred own branch';
 res:=hn.api(jsonb_build_object('action','assign','sessionToken',admin_session,'userId',learner,'assigned',b));ASSERT NOT(res ? 'error'),res::text;
 ASSERT (SELECT count(*) FROM hn.users WHERE id IN (learner,child,grandchild) AND assigned=b)=3,'Branch transfer failed';
 st:=hn.api(jsonb_build_object('action','state','sessionToken',s1));ASSERT jsonb_array_length(st->'people')=0,'Old staff retained branch';
 st:=hn.api(jsonb_build_object('action','state','sessionToken',s2));ASSERT jsonb_array_length(st->'people')=3,'New staff cannot see all layers';
 res:=hn.api(jsonb_build_object('action','registerZoom','name','TEST Người mới sau chuyển','phone','0990000006','consent',true,'ref',code_g));SELECT id INTO new_child FROM hn.users WHERE username='0990000006';ASSERT (SELECT assigned FROM hn.users WHERE id=new_child)=b,'New descendant failed to inherit transferred ownership';
 res:=hn.api(jsonb_build_object('action','touch','sessionToken',s1,'userId',child,'result','Đã liên hệ','note','Không được phép'));ASSERT res ? 'error','Previous staff accessed transferred CRM';
 res:=hn.api(jsonb_build_object('action','touch','sessionToken',s2,'userId',grandchild,'result','Đã liên hệ','note','Đã trao đổi'));ASSERT NOT(res ? 'error'),res::text;
 SELECT id INTO regid FROM hn.registrations WHERE user_id=child AND program='one' LIMIT 1;
 FOR i IN 1..2 LOOP res:=hn.api(jsonb_build_object('action','confirmAttendance','sessionToken',admin_session,'id',regid));ASSERT NOT(res ? 'error'),res::text;END LOOP;
 ASSERT (SELECT count(*) FROM hn.attendance WHERE ref_id=learner)=1,'Attendance double counted';
 FOR i IN 1..2 LOOP res:=hn.api(jsonb_build_object('action','confirmPaid','sessionToken',s2,'userId',child));ASSERT NOT(res ? 'error'),res::text;END LOOP;
 ASSERT (SELECT sum(amount) FROM hn.credits WHERE user_id=learner)=200000,'Credit double counted';
 FOR k IN 7..9 LOOP
  res:=hn.api(jsonb_build_object('action','registerZoom','name','TEST Đủ phước đức '||k,'phone','099000000'||k,'consent',true,'ref',code_l));SELECT id INTO uid FROM hn.users WHERE username='099000000'||k;
  res:=hn.api(jsonb_build_object('action','confirmPaid','sessionToken',s2,'userId',uid));ASSERT NOT(res ? 'error'),res::text;
 END LOOP;
 ASSERT (SELECT sum(amount) FROM hn.credits WHERE user_id=learner)=800000,'Excess credit not retained';
 res:=hn.api(jsonb_build_object('action','approveSix','sessionToken',s2,'userId',learner));ASSERT NOT(res ? 'error'),res::text;
 ASSERT (SELECT mtd FROM hn.users WHERE id=learner)=1,'MTD approval failed';
 ASSERT (SELECT sum(amount) FROM hn.credits WHERE user_id=learner)=800000,'Credit deducted unexpectedly';
 res:=hn.api(jsonb_build_object('action','login','username','0990000003','password','123456'));ASSERT res->>'sessionToken' IS NOT NULL,'Default password failed';
 res:=hn.api(jsonb_build_object('action','passwordChange','sessionToken',learner_session,'currentPassword','123456','newPassword','TestPass987'));ASSERT NOT(res ? 'error'),res::text;
 res:=hn.api(jsonb_build_object('action','login','username','0990000003','password','123456'));ASSERT res ? 'error','Old password still works';
 res:=hn.api(jsonb_build_object('action','login','username','0990000003','password','TestPass987'));ASSERT res->>'sessionToken' IS NOT NULL,'Changed password fails';
 res:=hn.api(jsonb_build_object('action','registerZoom','name','TEST Trùng số','phone','+84990000003','consent',true));ASSERT res ? 'error','Duplicate phone accepted';
 res:=hn.api(jsonb_build_object('action','createLead','sessionToken',learner_session,'name','TEST Khai báo','phone','0990000010','consent',true));ASSERT res->>'createdLead'='true' AND NOT(res ? 'account'),'Learner received another account credentials';
 res:=hn.api(jsonb_build_object('action','role','sessionToken',admin_session,'userId',b,'role','student'));ASSERT NOT(res ? 'error'),res::text;
 st:=hn.api(jsonb_build_object('action','state','sessionToken',s2));ASSERT NOT(st->>'staff')::boolean,'Demoted staff retains rights';ASSERT jsonb_array_length(st->'people')=0,'Demoted staff retained data';
 ASSERT NOT has_table_privilege('anon','hn.users','SELECT'),'Anon can read raw users';
 ASSERT NOT has_table_privilege('authenticated','hn.users','SELECT'),'Authenticated can read raw users';
 RAISE NOTICE 'PASS: admin/default passwords, approved staff only, multilevel inheritance, transfer of whole branch, future descendants, lost previous permissions, names-only learner view, CRM checks, idempotency, 800k retention and password change.';
END $$;
SELECT 'PASS: all transactional Supabase checks completed; test records rolled back' AS verification;
ROLLBACK;
